/* Frees our network device */
static void hso_free_net_device(struct hso_device *hso_dev, bool bailout)
{
	int i;
	struct hso_net *hso_net = dev2net(hso_dev);

	if (!hso_net)
		return;

	remove_net_device(hso_net->parent);

	if (hso_net->net)
